// WF-1 init — build the state object per 02 §3
const body = $input.first().json.body || $input.first().json;
const goal = body.goal || body.input || $input.first().json.goal || "reverse this string: hello";
const task_id = `task-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
const state = {
  schema_version: 1,
  task_id: task_id,
  goal: String(goal),
  loop: { gate: "audit", remaining: 3 },
  recall: { reusable_tools: [], mutation_constraints: [] },
  candidate: null,
  test: { passed: false, runs: [] },
  audit: { security_pass: true, edge_case_pass: true, objections: [] },
  outcome: { status: "", final_answer: "" }
};
let toolInput = String(goal);
const m = /:\s*"?([^"\n]+)"?\s*$/.exec(toolInput);
if (m) toolInput = m[1].trim();
state.test.runs = [];
return [{ json: { ...state, _toolInput: toolInput } }];

// WF-1 audit gate — Switch logic as Code Node (n8n Switch needs explicit boolean)
const state = $input.first().json;
const sec = state.audit?.security_pass;
const edge = state.audit?.edge_case_pass;
const remaining = state.loop?.remaining ?? 0;
let decision;
if (sec && edge) decision = "deploy";
else if (remaining > 0) decision = "rework";
else decision = "failed";
return [{ json: { ...state, _auditDecision: decision } }];

// WF-1 rework loop — decrement remaining, route back to Lab with objections
const state = $input.first().json;
const next = JSON.parse(JSON.stringify(state));
next.loop.remaining = (next.loop.remaining || 1) - 1;
if (next.loop.remaining < 0) next.loop.remaining = 0;
// audit.objections already contains Security + Critic blocks — Lab will see them via state.audit.objections
// Also push a swarm_log row for the rework gate
return [{ json: next }];

// WF-1 failed — loop exhausted, log to problem_store via swarm_log
const state = $input.first().json;
return [{ json: {
  task_id: state.task_id,
  workflow: "wf1-main-router",
  gate: "audit-exhausted",
  verdict: `failed after ${3 - (state.loop.remaining||0)} reworks: ${JSON.stringify(state.audit.objections||[]).slice(0,500)}`,
  duration_ms: 0,
  state
} }];
